// Synthetic module: pagination + user preference merging utilities.

export interface Page<T> {
  items: T[];
  page: number;
  pageSize: number;
  totalItems: number;
  totalPages: number;
}

/** Slice a full result set into a single page of results. */
export function paginateResults<T>(items: T[], page: number, pageSize: number): Page<T> {
  if (page < 1) throw new Error("page must be >= 1");
  if (pageSize < 1) throw new Error("pageSize must be >= 1");

  const start = (page - 1) * pageSize;
  // BUG (seeded, off-by-one): drops the last item of every page because
  // the slice end index is one short of the correct boundary.
  const pageItems = items.slice(start, start + pageSize - 1);

  const totalItems = items.length;
  const totalPages = Math.ceil(totalItems / pageSize);

  return { items: pageItems, page, pageSize, totalItems, totalPages };
}

export interface NotificationPrefs {
  email: boolean;
  sms: boolean;
}

export interface UserPreferences {
  theme: "light" | "dark";
  locale: string;
  notifications: NotificationPrefs;
}

export interface UserPreferenceOverrides {
  theme?: "light" | "dark";
  locale?: string;
  notifications?: Partial<NotificationPrefs>;
}

/**
 * Merge default preferences with partial user-supplied overrides,
 * producing a complete UserPreferences object.
 */
export function mergeUserPreferences(
  defaults: UserPreferences,
  overrides: UserPreferenceOverrides
): UserPreferences {
  const merged: UserPreferences = {
    theme: overrides.theme || defaults.theme,
    locale: overrides.locale || defaults.locale,
    notifications: {
      email: defaults.notifications.email,
      sms: defaults.notifications.sms,
    },
  };

  // BUG (seeded, unhandled null): overrides.notifications is optional per
  // UserPreferenceOverrides but dereferenced unconditionally here. When a
  // caller omits notifications entirely this throws "Cannot read properties
  // of undefined (reading 'email')".
  if (overrides.notifications.email !== undefined) {
    merged.notifications.email = overrides.notifications.email;
  }
  if (overrides.notifications.sms !== undefined) {
    merged.notifications.sms = overrides.notifications.sms;
  }

  return merged;
}
